PAYLOAD=json.loads('{"src/katarina/monitoring/entry_feed.py": "\\"\\"\\"Read-only entry history and candidate plans, with explicit provenance and no account fields.\\"\\"\\"\\nfrom contextlib import closing\\nfrom datetime import datetime, timezone\\nimport hashlib\\nimport json\\nimport math\\nfrom pathlib import Path\\nimport re\\nimport sqlite3\\n\\nfrom katarina.monitoring.worker_runtime import _read, _fresh\\n\\n\\ndef _stamp(value):\\n    try:\\n        t = datetime.fromtimestamp(value, timezone.utc)\\n        return t.isoformat()\\n    except (ValueError, TypeError, OverflowError, OSError):\\n        return None\\n\\n\\ndef _price(value):\\n    return value if type(value) in (int, float) and math.isfinite(value) and 0 < value < 1e12 else None\\n\\n\\ndef _symbol(value):\\n    return value if isinstance(value, str) and re.fullmatch(r\'[A-Za-z0-9_.#-]{1,40}\', value) else None\\n\\n\\ndef _db(path):\\n    db = sqlite3.connect(path.resolve().as_uri()+\'?mode=ro\', uri=True, timeout=.25)\\n    db.execute(\'PRAGMA query_only=ON\')\\n    db.execute(\'BEGIN\')\\n    return db\\n\\n\\ndef read_entry_feed(root, *, allowed, now=None):\\n    now = now or datetime.now(timezone.utc)\\n    root = Path(root)\\n    empty = dict(status=\'NOT_ATTESTED\', history=[], plans=[])\\n    executor = _read(root/\'demo-forward/executor.json\')\\n    decision = _read(root/\'demo-forward/status.json\')\\n    if not (allowed and executor.get(\'independent\') is True and executor.get(\'mode\') == \'DEMO\'\\n            and type(executor.get(\'pid\')) is int and executor[\'pid\'] > 0 and _fresh(executor, now)\\n            and decision.get(\'pid\') == executor[\'pid\'] and _fresh(decision, now)\\n            and decision.get(\'live_authorized\') is False):\\n        return empty\\n    out = dict(status=\'OBSERVED\', as_of_utc=decision[\'as_of_utc\'], executor_pid=executor[\'pid\'],\\n               source=\'KATARINA_DEMO_LEDGER\', mode=\'DEMO\', history=[], plans=[],\\n               history_status=\'NOT_ATTESTED\', plans_status=\'NOT_ATTESTED\', live_authorized=False)\\n    try:\\n        with closing(_db(root/\'demo-forward/orders.sqlite3\')) as orders:\\n            out[\'history_total\'] = orders.execute(\\"SELECT COUNT(*) FROM demo_outbox WHERE state IN (\'OPEN\',\'CLOSED\')\\").fetchone()[0]\\n            rows = orders.execute(\\"SELECT intent_id,state,updated_at,intent_json,outcome_json FROM demo_outbox WHERE state IN (\'OPEN\',\'CLOSED\') ORDER BY updated_at DESC,intent_id LIMIT 20\\").fetchall()\\n        for ident, state, updated, raw, outcome in rows:\\n            try:\\n                intent = json.loads(raw)\\n                stamp = _stamp(intent.get(\'created_at\'))\\n                if not (isinstance(ident, str) and _symbol(intent.get(\'symbol\')) and intent.get(\'side\') in (\'BUY\',\'SELL\')\\n                        and stamp and -30 <= now.timestamp()-intent[\'created_at\']):\\n                    continue\\n                row = dict(id=hashlib.sha256(ident.encode()).hexdigest()[:24], symbol=intent[\'symbol\'],\\n                           side=intent[\'side\'], state=state, decision_utc=stamp,\\n                           requested_price=_price(intent.get(\'price\')), stop_loss=_price(intent.get(\'stop_loss\')),\\n                           take_profit=_price(intent.get(\'take_profit\')), fill_price_verified=False)\\n                if state == \'CLOSED\':\\n                    closed = json.loads(outcome or \'{}\')\\n                    row[\'closed_observed_utc\'] = _stamp(closed.get(\'closed_observed_at\'))\\n                try:\\n                    with closing(_db(root/\'demo-forward/experiment.sqlite3\')) as cache:\\n                        variant = cache.execute(\'SELECT report_json FROM demo_variants WHERE id=?\',(intent.get(\'experiment_id\'),)).fetchone()\\n                    params = json.loads(variant[0]).get(\'parameters\',{}) if variant else {}\\n                    if params.get(\'method\') in (\'MOMENTUM\',\'MEAN_REVERSION\',\'BREAKOUT\'):\\n                        row[\'method\'] = params[\'method\']\\n                    if params.get(\'horizon\') in (4,12,24):\\n                        row[\'horizon\'] = params[\'horizon\']\\n                except (sqlite3.Error, OSError, ValueError, TypeError, AttributeError):\\n                    pass\\n                out[\'history\'].append(row)\\n            except (ValueError, TypeError, AttributeError):\\n                continue\\n        out[\'history_status\'] = \'OBSERVED\'\\n    except (sqlite3.Error, OSError):\\n        pass\\n    try:\\n        with closing(_db(root/\'demo-forward/experiment.sqlite3\')) as cache, closing(_db(root/\'experiment-jobs.sqlite3\')) as research:\\n            rows = cache.execute(\'SELECT v.id,v.trial_id,v.report_json,c.last_checked FROM demo_variants v LEFT JOIN demo_candidate_visits c ON c.trial_id=v.trial_id ORDER BY c.last_checked DESC,v.id LIMIT 12\').fetchall()\\n            for ident, trial, raw, checked in rows:\\n                try:\\n                    if not re.fullmatch(\'[a-f0-9]{64}\', ident):\\n                        continue\\n                    report = json.loads(raw)\\n                    policy = cache.execute(\'SELECT report_json FROM demo_policy_reviews WHERE variant_id=? ORDER BY rowid DESC LIMIT 1\',(ident,)).fetchone()\\n                    if policy:\\n                        report = json.loads(policy[0])\\n                    params = report.get(\'parameters\') or {}\\n                    symbol = research.execute(\'SELECT symbol FROM trials WHERE id=?\',(trial,)).fetchone()\\n                    if not symbol or not _symbol(symbol[0]) or params.get(\'method\') not in (\'MOMENTUM\',\'MEAN_REVERSION\',\'BREAKOUT\') or params.get(\'side\') not in (\'BUY\',\'SELL\'):\\n                        continue\\n                    if params.get(\'lookback\') not in (12,24,48) or params.get(\'horizon\') not in (4,12,24) or params.get(\'threshold\') not in (.5,1,1.5):\\n                        continue\\n                    lesson = cache.execute(\'SELECT report_json FROM demo_lessons WHERE variant_id=?\',(ident,)).fetchone()\\n                    cooldown = lesson and json.loads(lesson[0]).get(\'decision\') == \'COOLDOWN_RESEARCH_REQUIRED\'\\n                    state = \'COOLDOWN\' if cooldown else \'AWAITING_SIGNAL_REVIEW\' if report.get(\'qualified\') is True else \'NOT_QUALIFIED\'\\n                    checks = [dict(multiplier=c[\'multiplier\'], passed=c.get(\'passed\') is True) for c in report.get(\'checks\',[]) if isinstance(c,dict) and c.get(\'multiplier\') in (1,2,3)]\\n                    out[\'plans\'].append(dict(id=ident[:24], symbol=symbol[0], side=params[\'side\'], method=params[\'method\'],\\n                        lookback=params[\'lookback\'], horizon=params[\'horizon\'], threshold=params[\'threshold\'],\\n                        state=state, last_reviewed_utc=_stamp(checked), checks=checks,\\n                        signal_verified=False, executable=False, stop_range=2, target_range=4))\\n                except (ValueError, TypeError, AttributeError):\\n                    continue\\n        out[\'plans_status\'] = \'OBSERVED\'\\n    except (sqlite3.Error, OSError):\\n        pass\\n    return out\\n", "src/katarina/monitoring/public_runtime.py": "\\"\\"\\"Reconstruct a technical-only, freshness-checked view without opening broker or memory.\\"\\"\\"\\nfrom pathlib import Path\\nimport json\\nfrom katarina.intelligence.runtime_evidence import read_runtime\\nfrom katarina.monitoring.agent_projection import project_agent_board\\nfrom katarina.monitoring.activity_trace import read_activity\\nfrom katarina.adapters.owner_dialog_server import public_dashboard_snapshot\\n\\ndef build_public_runtime(root):\\n    root=Path(root)\\n    try:\\n        status=json.loads((root/\'continuous-status.json\').read_text(encoding=\'utf-8\'))\\n    except (OSError,ValueError):\\n        status={}\\n    evidence=read_runtime(root)\\n    board=project_agent_board(evidence,delivery=status.get(\'delivery\',\'UNVERIFIED\'))\\n    activity=read_activity(root)\\n    pid=status.get(\'pid\')\\n    board[\'current_process_pid\']=pid\\n    market_process_matches=evidence.get(\'operational\',{}).get(\'snapshot_pid\')==pid\\n    board[\'snapshot_process_matches\']=bool(type(pid) is int and activity.get(\'pid\')==pid and activity.get(\'fresh\'))\\n    if not market_process_matches:\\n        board[\'result\']=\'BLOCKED\'\\n    if status.get(\'status\') in (\'STOPPED\',\'BLOCKED\'):\\n        board[\'result\']=\'BLOCKED\'\\n    board[\'model\']={\'configured\':status.get(\'model_configured\') is True,\\n                    \'telemetry\':status.get(\'model_telemetry\',{})}\\n    board[\'activity\']=activity\\n    public = public_dashboard_snapshot({\'agent_board\':board})\\n    from katarina.monitoring.learning_evidence import read_learning\\n    from katarina.monitoring.public_research import read_public_research\\n    allowed = board[\'snapshot_process_matches\'] and board.get(\'result\') == \'SNAPSHOT_PASS\'\\n    research_allowed = bool(board[\'snapshot_process_matches\'] and status.get(\'delivery\') == \'DISABLED\'\\n        and status.get(\'live_execution_authorized\') is False and status.get(\'orders_submitted\') == 0\\n        and status.get(\'status\') in (\'WAITING\',\'OBSERVING\',\'DEGRADED\'))\\n    # Sensor completeness and persisted research provenance are separate attestations.\\n    try:\\n        with (root/\'latest.json\').open(\'rb\') as stream:\\n            raw=stream.read(2_000_001)\\n        observation_stamp=json.loads(raw)[\'observed_at_utc\'] if len(raw)<=2_000_000 else None\\n    except (OSError,ValueError,KeyError):\\n        observation_stamp=None\\n    graph, entries = read_public_research(root,observation_stamp) if research_allowed else (\\n        {\'schema_version\':1,\'nodes\':[],\'edges\':[],\'status\':\'NOT_ATTESTED\'},\\n        {\'status\':\'NOT_ATTESTED\',\'positions\':[]})\\n    if research_allowed and graph.get(\'status\')==\'NOT_ATTESTED\':\\n        from katarina.monitoring.public_research import worker_research_runs,graph_from_report\\n        runs=worker_research_runs(root)\\n        if runs:graph=graph_from_report({\'continuous_research_lab\':{\'recent\':runs}})\\n    public_board=public[\'agent_board\']\\n    # Process activity, market completeness and learning are distinct evidence scopes.\\n    from datetime import datetime, timezone\\n    try:\\n        heartbeat_age=(datetime.now(timezone.utc)-datetime.fromisoformat(status[\'heartbeat_utc\'])).total_seconds()\\n    except (KeyError,ValueError,TypeError):\\n        heartbeat_age=float(\'inf\')\\n    public_board[\'telemetry_verified\']=bool(research_allowed and status.get(\'production_execution\') is False\\n                                           and (-30<=heartbeat_age<=180 or activity.get(\'fresh\') is True))\\n    public_board[\'market_snapshot_verified\']=board.get(\'result\')==\'SNAPSHOT_PASS\'\\n    public_board[\'sensor_blockers\']=evidence.get(\'blockers\',[])\\n    public_board[\'learning\']=(read_learning(root,observation_utc=observation_stamp)\\n                              if public_board[\'telemetry_verified\'] else {\'status\':\'NOT_ATTESTED\'})\\n    from katarina.monitoring.research_growth import read_growth\\n    public_board[\'research_growth\']=read_growth(root,pid) if research_allowed else {\'status\':\'NOT_ATTESTED\'}\\n    public_board[\'research_graph\']=graph\\n    from katarina.intelligence.research_reports import read_reports\\n    public_board[\'research_reports\']=read_reports(root,pid) if research_allowed else {\'status\':\'NOT_ATTESTED\'}\\n    from katarina.monitoring.research_lab_status import read_lab_status\\n    public_board[\'research_lab\'] = read_lab_status(root) if research_allowed else {\'status\':\'NOT_ATTESTED\'}\\n    from katarina.intelligence.data_recovery import read_recovery\\n    public_board[\'research_lab\'][\'recovery\']=read_recovery(root,pid) if research_allowed else {\'status\':\'NOT_ATTESTED\'}\\n    public_board[\'research_source_verified\'] = research_allowed and graph.get(\'status\') != \'NOT_ATTESTED\'\\n    public_board[\'entries\']=entries\\n    public_board[\'market_symbols\']=None\\n    public_board[\'operational\']={}\\n    public_board[\'learning\'].pop(\'no_signal_observations\',None)\\n    trace=public_board[\'activity\']\\n    trace[\'events\']=[{k:e[k] for k in (\'seq\',\'at_utc\',\'phase\',\'state\')} for e in trace[\'events\']]\\n    trace[\'current\']=trace[\'events\'][-1] if trace[\'events\'] else None\\n    from katarina.monitoring.worker_runtime import read_worker_runtime\\n    public_board[\'worker_runtime\']=read_worker_runtime(root,pid)\\n    public_board[\'public_scope\']=\'RESEARCH_GRAPH_AND_ENTRY_ONLY\'\\n    from katarina.monitoring.pair_activity import read_pair_activity\\n    public_board[\'pair_activity\']=read_pair_activity(root,pid,allowed=public_board.get(\'telemetry_verified\') is True and board[\'snapshot_process_matches\'])\\n    from katarina.monitoring.entry_feed import read_entry_feed\\n    public_board[\'entry_feed\']=read_entry_feed(root,allowed=research_allowed)\\n    return public\\n", "tests/unit/test_entry_feed.py": "import json\\nfrom contextlib import closing\\nfrom pathlib import Path\\nimport sqlite3\\nimport tempfile\\nimport unittest\\nfrom datetime import datetime, timezone, timedelta\\nfrom katarina.monitoring.entry_feed import read_entry_feed\\n\\nclass EntryFeedTests(unittest.TestCase):\\n    def test_verified_history_plans_redaction_and_readonly(self):\\n        with tempfile.TemporaryDirectory() as temp:\\n            root=Path(temp);private=root/\'demo-forward\';private.mkdir();now=datetime.now(timezone.utc)\\n            for name,doc in [(\'executor\',dict(pid=7,independent=True,mode=\'DEMO\',as_of_utc=now.isoformat())),(\'status\',dict(pid=7,as_of_utc=now.isoformat(),live_authorized=False))]:\\n                (private/(name+\'.json\')).write_text(json.dumps(doc))\\n            with closing(sqlite3.connect(private/\'orders.sqlite3\')) as db, db:\\n                db.execute(\'CREATE TABLE demo_outbox(intent_id,state,updated_at,intent_json,outcome_json)\')\\n                intent=dict(symbol=\'XAUUSD.vx\',side=\'BUY\',price=4000,stop_loss=3990,take_profit=4020,created_at=now.timestamp()-60,volume=99,login=\'SECRET\')\\n                db.execute(\'INSERT INTO demo_outbox VALUES(?,?,?,?,?)\',(\'entry\',\'CLOSED\',now.timestamp(),json.dumps(intent),json.dumps(dict(closed_observed_at=now.timestamp(),net_profit_native=99))))\\n                db.execute(\'INSERT INTO demo_outbox VALUES(?,?,?,?,?)\',(\'unconfirmed\',\'ACCEPTED\',now.timestamp(),json.dumps(intent),None))\\n            ident=\'a\'*64;trial=\'b\'*64\\n            report=dict(qualified=False,parameters=dict(method=\'MOMENTUM\',side=\'BUY\',lookback=24,horizon=4,threshold=.5),checks=[dict(multiplier=1,passed=False)],secret=\'SECRET\')\\n            with closing(sqlite3.connect(private/\'experiment.sqlite3\')) as db, db:\\n                db.execute(\'CREATE TABLE demo_variants(id,trial_id,report_json)\');db.execute(\'INSERT INTO demo_variants VALUES(?,?,?)\',(ident,trial,json.dumps(report)))\\n                db.execute(\'CREATE TABLE demo_candidate_visits(trial_id,last_checked)\');db.execute(\'INSERT INTO demo_candidate_visits VALUES(?,?)\',(trial,now.timestamp()))\\n                db.execute(\'CREATE TABLE demo_policy_reviews(variant_id,report_json)\');db.execute(\'CREATE TABLE demo_lessons(variant_id,report_json)\')\\n            with closing(sqlite3.connect(root/\'experiment-jobs.sqlite3\')) as db, db:\\n                db.execute(\'CREATE TABLE trials(id,symbol)\');db.execute(\'INSERT INTO trials VALUES(?,?)\',(trial,\'XAUUSD.vx\'))\\n            before={str(p):p.read_bytes() for p in root.rglob(\'*.sqlite3\')}\\n            feed=read_entry_feed(root,allowed=True,now=now)\\n            self.assertEqual(len(feed[\'history\']),1);self.assertEqual(feed[\'history\'][0][\'state\'],\'CLOSED\')\\n            self.assertEqual(feed[\'plans\'][0][\'state\'],\'NOT_QUALIFIED\');self.assertFalse(feed[\'plans\'][0][\'executable\'])\\n            raw=json.dumps(feed);self.assertNotIn(\'SECRET\',raw);self.assertNotIn(\'volume\',raw);self.assertNotIn(\'net_profit_native\',raw)\\n            for p,data in before.items():self.assertEqual(Path(p).read_bytes(),data)\\n            self.assertEqual(read_entry_feed(root,allowed=False,now=now)[\'status\'],\'NOT_ATTESTED\')\\n            self.assertEqual(read_entry_feed(root,allowed=True,now=now+timedelta(minutes=3))[\'status\'],\'NOT_ATTESTED\')\\n            (private/\'status.json\').write_text(json.dumps(dict(pid=8,as_of_utc=now.isoformat(),live_authorized=False)))\\n            self.assertEqual(read_entry_feed(root,allowed=True,now=now)[\'status\'],\'NOT_ATTESTED\')\\n\\n    def test_missing_databases_are_not_empty_verified_history(self):\\n        with tempfile.TemporaryDirectory() as temp:\\n            root=Path(temp);p=root/\'demo-forward\';p.mkdir();now=datetime.now(timezone.utc)\\n            (p/\'executor.json\').write_text(json.dumps(dict(pid=1,independent=True,mode=\'DEMO\',as_of_utc=now.isoformat())))\\n            (p/\'status.json\').write_text(json.dumps(dict(pid=1,live_authorized=False,as_of_utc=now.isoformat())))\\n            feed=read_entry_feed(root,allowed=True,now=now)\\n            self.assertEqual(feed[\'history_status\'],\'NOT_ATTESTED\');self.assertEqual(feed[\'plans_status\'],\'NOT_ATTESTED\')\\n            self.assertFalse((p/\'orders.sqlite3\').exists())\\n"}')
